                String.valueOf(r.id()),
                String.valueOf(r.roomNumber()),
                r.checkIn().toString(),
                r.checkOut().toString(),
                String.valueOf(r.guests()),
                String.valueOf(r.nights()),
                Money.plain(tax(r)))).toList();
